17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (hasReachedCityCapacity(owner.getCity())) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
121	        owner.setCity(normalizeCity(owner.getCity()));
122	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    /**
131	     * The maximum number of owners that may be registered on any single day.
132	     */
133	    private static final long MAX_OWNERS_PER_DAY = 20;
134	
135	    /**
136	     * Determines whether the number of owners already registered on the given date has reached the
137	     * daily registration limit. When 20 owners share the same registration date, no further owner may
138	     * be created for that day.
139	     */
140	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
141	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
142	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
143	            .count();
144	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
145	    }
146	
147	    /**
148	     * The maximum number of owners that may share a single city.
149	     */
150	    private static final long MAX_OWNERS_PER_CITY = 8;
151	
152	    /**
153	     * Determines whether the given city has already reached its capacity of owners. When a city
154	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
155	     * ignoring letter case.
156	     */
157	    private boolean hasReachedCityCapacity(String city) {
158	        if (city == null) {
159	            return false;
160	        }
161	        long ownersInCity = this.clinicService.findAllOwners().stream()
162	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
163	            .count();
164	        return ownersInCity >= MAX_OWNERS_PER_CITY;
165	    }
166	
167	    /**
168	     * Generates the customer code for a newly created owner. The code is formatted as
169	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
170	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
171	     * Cities are matched ignoring letter case.
172	     */
173	    private String generateCustomerCode(String city) {
174	        long ownersInCity = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
176	            .count();
177	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
178	    }
179	
180	    /**
181	     * Normalizes the city of a newly created owner. If an owner already exists in the same
182	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
183	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
184	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
185	     * lowercasing the rest, so for example "new york" becomes "New York".
186	     */
187	    private String normalizeCity(String city) {
188	        if (city == null) {
189	            return null;
190	        }
191	        return this.clinicService.findAllOwners().stream()
192	            .map(Owner::getCity)
193	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
194	            .findFirst()
195	            .orElseGet(() -> toTitleCase(city));
196	    }
197	
198	    /**
199	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
200	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
201	     * "new  YORK" becomes "New  York".
202	     */
203	    private static String toTitleCase(String value) {
204	        StringBuilder result = new StringBuilder(value.length());
205	        boolean capitalizeNext = true;
206	        for (int i = 0; i < value.length(); i++) {
207	            char c = value.charAt(i);
208	            if (Character.isWhitespace(c)) {
209	                capitalizeNext = true;
210	                result.append(c);
211	            } else if (capitalizeNext) {
212	                result.append(Character.toTitleCase(c));
213	                capitalizeNext = false;
214	            } else {
215	                result.append(Character.toLowerCase(c));
216	            }
217	        }
218	        return result.toString();
219	    }
220	
221	    /**
222	     * Determines whether an owner already exists that uses the same telephone number
223	     * as the given one. Telephone numbers must be unique across all owners. The
224	     * comparison ignores letter case and any surrounding or repeated whitespace.
225	     */
226	    private boolean isDuplicateOwner(Owner owner) {
227	        String telephone = normalizeTelephone(owner.getTelephone());
228	        return this.clinicService.findAllOwners().stream()
229	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
230	    }
231	
232	    /**
233	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
234	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
235	     * "6135550100". This lets differently punctuated forms of the same number be treated as
236	     * equal for the uniqueness check and stored in a single canonical form.
237	     */
238	    private static String normalizeTelephone(String telephone) {
239	        if (telephone == null) {
240	            return null;
241	        }
242	        return telephone.replaceAll("[\\s()-]", "");
243	    }
244	
245	    /**
246	     * Determines whether another owner already uses the same email address as the given one.
247	     * Email addresses, when supplied, must be unique across all owners. An owner without an
248	     * email address is never considered a duplicate. The comparison ignores letter case and
249	     * any surrounding or repeated whitespace.
250	     */
251	    private boolean isDuplicateEmail(Owner owner) {
252	        String email = normalize(owner.getEmail());
253	        if (email == null || email.isEmpty()) {
254	            return false;
255	        }
256	        return this.clinicService.findAllOwners().stream()
257	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
258	    }
259	
260	    /**
261	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
262	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
263	     * and "John Smith" normalize to the same key and so count as the same person.
264	     */
265	    private static String normalize(String value) {
266	        if (value == null) {
267	            return null;
268	        }
269	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
275	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
276	        if (currentOwner == null) {
277	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	        }
279	        currentOwner.setAddress(ownerFieldsDto.getAddress());
280	        currentOwner.setCity(ownerFieldsDto.getCity());
281	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
282	        currentOwner.setLastName(ownerFieldsDto.getLastName());
283	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
284	        this.clinicService.saveOwner(currentOwner);
285	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Transactional
290	    @Override
291	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        this.clinicService.deleteOwner(owner);
297	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
298	    }
299	
300	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
301	    @Override
302	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
303	        Owner owner = this.clinicService.findOwnerById(ownerId);
304	        if (owner == null) {
305	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
306	        }
307	        HttpHeaders headers = new HttpHeaders();
308	        Pet pet = petMapper.toPet(petFieldsDto);
309	        owner.setId(ownerId);
310	        pet.setOwner(owner);
